ReplacementContent:
"                                         {/* Bullet Circles */}
                                         <div className="absolute inset-0 w-full h-full pointer-events-none">
                                           {points.map((p, idx) => (
                                             <div 
                                               key={idx}
                                               className="absolute w-2.5 h-2.5 rounded-full bg-[#3b82f6] hover:bg-emerald-500 border border-white shadow-sm -translate-x-1/2 -translate-y-1/2 cursor-pointer group pointer-events-auto transition-all"
                                               style={{ left: `${p.x}%`, top: `${p.y}%` }}
                                             >
                                               {/* Tooltip */}
                                               <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-1.5 hidden group-hover:block bg-slate-900 text-white text-[9px] font-bold py-1 px-1.5 rounded shadow-lg whitespace-nowrap z-50">
                                                 {formatDateLabel(p.day, p.isMonth)}: {config.currency} {parseFloat(p.total || 0).toFixed(2)}
                                               </div>
                                             </div>
                                           ))}
                                         </div>"

